INSERT INTO production_product (id, category_id, product_line_id, code, slug, name, base_price, target_audience, skill_level, description, care_instructions, specifications, size_chart, tags, status) VALUES
(1, 6, 2, 'SWIM-W01', 'ao-tam-1-manh-soobin-elegance', 'Áo Tắm 1 Mảnh Liền Thân Soobin Elegance Khoét Lưng', 520000.00, 'Nữ', 'Bơi lội thể thao', 'Áo tắm liền thân thiết kế tôn dáng cực kỳ quyến rũ với phần lưng khoét chữ U thanh lịch, đệm mút cao cấp nâng đỡ tự nhiên.', 'Giặt tay bằng nước lạnh, không dùng chất tẩy mạnh.', '{"fabric": "82% Polyamide, 18% Spandex", "padding": "Có đệm mút tháo rời", "uv_protection": "UPF 50+"}', '{"S": {"chest": "80-84cm", "waist": "62-66cm", "hips": "86-90cm"}, "M": {"chest": "85-89cm", "waist": "67-71cm", "hips": "91-95cm"}, "L": {"chest": "90-94cm", "waist": "72-76cm", "hips": "96-100cm"}}', ARRAY['do-boi-nu', 'ao-tam-1-manh', 'chong-nang', 'resort'], 'Selling'),
(2, 5, 2, 'SWIM-W02', 'bikini-2-manh-soobin-coral-beach', 'Bộ Bikini 2 Mảnh Soobin Coral Beach Cạp Cao', 480000.00, 'Nữ', 'Nghỉ dưỡng', 'Bikini hai mảnh cạp cao phong cách hiện đại giúp khéo léo che khuyết điểm vòng 2, gam màu san hô rực rỡ dưới ánh nắng hè.', 'Xả sạch với nước sau khi tắm biển, phơi nơi thoáng gió.', '{"fabric": "Chống Clo, co giãn 4 chiều", "lining": "2 lớp vải lót kháng khuẩn"}', '{"S": {"chest": "78-83cm", "waist": "60-65cm"}, "M": {"chest": "84-88cm", "waist": "66-70cm"}}', ARRAY['bikini', 'cap-cao', 'do-boi-nu'], 'Selling'),
(3, 7, 1, 'SWIM-M01', 'quan-boi-nam-soobin-speed-pro', 'Quần Bơi Nam Soobin Speed Pro Ôm Sát Chuyên Nghiệp', 350000.00, 'Nam', 'Chuyên nghiệp', 'Quần bơi nam thiết kế lướt nước tối ưu cho các buổi tập luyện và thi đấu thể thao, giảm tối đa ma sát trong nước.', 'Không giặt máy sấy khô, không ngâm xà phòng quá 30 phút.', '{"drying": "Công nghệ QuickDry mau khô trong 15 phút", "waist": "Dây rút co giãn chắc chắn"}', '{"M": {"waist": "74-78cm", "weight": "55-65kg"}, "L": {"waist": "79-84cm", "weight": "65-75kg"}, "XL": {"waist": "85-90cm", "weight": "75-85kg"}}', ARRAY['quan-boi-nam', 'the-thao', 'chuyen-nghiep'], 'Selling'),
(4, 8, 2, 'SWIM-M02', 'quan-boi-boxer-nam-soobin-ocean-wave', 'Quần Bơi Boxer Nam Đi Biển Họa Tiết Sóng Biển', 320000.00, 'Nam', 'Nghỉ dưỡng', 'Quần short bơi dáng boxer trẻ trung, năng động với túi sau tiện lợi, có thể mặc bơi hoặc dạo biển du lịch.', 'Giặt ở chế độ nhẹ, tránh phơi trực tiếp dưới nắng gắt.', '{"pockets": "2 túi bên + 1 túi khóa dán", "mesh": "Lót lưới mềm bên trong"}', '{"M": {"waist": "72-78cm"}, "L": {"waist": "78-84cm"}, "XL": {"waist": "84-92cm"}}', ARRAY['quan-boi-boxer', 'di-bien', 'nam'], 'Selling'),
(5, 10, 1, 'SWIM-ACC01', 'kinh-boi-soobin-anti-fog-wide-view', 'Kính Bơi Chống Đọng Sương Góc Rộng Soobin Pro', 220000.00, 'Unisex', 'Mới tập bơi', 'Kính bơi tráng gương bảo vệ mắt khỏi tia UV, tròng kính tráng nano chống đọng sương (anti-fog) cho tầm nhìn siêu trong.', 'Tránh chạm tay vào mặt trong kính để giữ lớp chống mờ.', '{"lens": "Polycarbonate chống trầy xước", "strap": "Silicone mềm tùy chỉnh"}', '{"FREESIZE": {"info": "3 cầu mũi thay thế vừa vặn mọi khuôn mặt"}}', ARRAY['kinh-boi', 'phu-kien', 'chong-tia-uv'], 'Selling'),
(6, 10, 1, 'SWIM-ACC02', 'mu-boi-silicone-soobin-hydrodynamic', 'Mũ Bơi Silicone Soobin Hydrodynamic Ôm Đầu Không Đau', 110000.00, 'Unisex', 'Bơi lội thể thao', 'Mũ bơi chất liệu 100% silicone cao cấp chống rách, bảo vệ tóc và da đầu khỏi hóa chất hồ bơi clo.', 'Rắc phấn rôm khi cất giữ để tránh dính mũ.', '{"material": "Silicone siêu dẻo không độc hại"}', '{"FREESIZE": {"info": "Co giãn tốt cho cả tóc ngắn và tóc dài"}}', ARRAY['mu-boi', 'phu-kien', 'silicone'], 'Selling'),
(7, 6, 4, 'SWIM-W03', 'ao-boi-chong-nang-tay-dai-soobin-uv-pro', 'Áo Bơi Chống Nắng Nữ Tay Dài Soobin UV-Pro Khóa Kéo', 590000.00, 'Nữ', 'Vận động ngoài trời', 'Áo bơi rashguard tay dài khóa kéo trước ngực tiện lợi, vải dệt UPF 50+ ngăn chặn 98% tia UVA/UVB khi lướt sóng và tắm biển.', 'Giặt tay nhẹ nhàng, phơi trong bóng râm.', '{"sun_protection": "UPF 50+ UV Block", "zip": "Khóa kéo YKK chống kẹt"}', '{"S": {"chest": "80-85cm", "height": "150-160cm"}, "M": {"chest": "86-90cm", "height": "158-168cm"}, "L": {"chest": "91-96cm", "height": "165-175cm"}}', ARRAY['ao-boi-tay-dai', 'rashguard', 'chong-nang', 'do-boi-nu'], 'Selling'),
(8, 9, 3, 'SWIM-K01', 'bo-do-boi-be-gai-cau-vong-soobin-kids', 'Bộ Đồ Bơi Bé Gái Cầu Vồng Soobin Kids Đáng Yêu', 290000.00, 'Trẻ em', 'Mới tập bơi', 'Đồ bơi 1 mảnh dành cho bé gái với họa tiết cầu vồng và hồng hạc rực rỡ, chất vải mềm mại không gây ngứa hay kích ứng làn da nhạy cảm.', 'Giặt riêng bằng nước lạnh.', '{"safety": "Không chứa formaldehyt, viền may êm ái", "fabric": "Co giãn 4 chiều mềm mịn"}', '{"XS": {"age": "2-3 tuổi", "weight": "11-15kg"}, "S": {"age": "4-5 tuổi", "weight": "16-20kg"}, "M": {"age": "6-7 tuổi", "weight": "21-26kg"}}', ARRAY['do-boi-tre-em', 'be-gai', 'cau-vong'], 'Selling'),
(9, 11, 4, 'SWIM-ACC03', 'tui-chong-nuoc-di-bien-soobin-dry-bag-20l', 'Túi Chống Nước Đa Năng Đi Biển Soobin Dry Bag 20L', 260000.00, 'Unisex', 'Nghỉ dưỡng', 'Túi khô chống nước tuyệt đối 20L chuyên dụng đi bơi, đi biển, chèo SUP hoặc lướt sóng, bảo vệ điện thoại ví tiền an toàn 100%.', 'Lau khô sau khi sử dụng, tránh vật nhọn đâm thủng.', '{"capacity": "20 Lít", "waterproof": "IPX6 chống ngập nước", "strap": "Có quai đeo vai tháo rời"}', '{"FREESIZE": {"dimensions": "Đường kính 24cm, cao 60cm khi mở"}}', ARRAY['tui-chong-nuoc', 'dry-bag', 'phu-kien-bien'], 'Selling'),
(10, 6, 1, 'SWIM-W04', 'ao-tam-the-thao-soobin-active-dynamic', 'Bộ Áo Tắm Liền Thân Thể Thao Soobin Active Dynamic', 490000.00, 'Nữ', 'Bơi lội thể thao', 'Dòng áo tắm thể thao chuyên sâu với đường cắt khí động học ôm sát cơ thể, giảm lực cản của nước, dây đai lưng chéo chữ X chắc chắn.', 'Không giặt với chất làm mềm vải.', '{"chlorine_resistant": "Kháng Clo gấp 10 lần vải thông thường", "support": "Lớp lót ngực nâng đỡ thể thao"}', '{"S": {"chest": "78-83cm"}, "M": {"chest": "84-89cm"}, "L": {"chest": "90-95cm"}}', ARRAY['do-boi-the-thao', 'lien-than', 'nu'], 'Selling'),
(11, 7, 1, 'SWIM-M03', 'quan-boi-nam-dai-ngang-goi-soobin-racing-pro', 'Quần Bơi Nam Dài Ngang Gối Soobin Racing Pro', 380000.00, 'Nam', 'Chuyên nghiệp', 'Quần bơi jammer dài ngang gối đạt chuẩn thi đấu, hỗ trợ nâng đỡ cơ bắp đùi, chống mỏi cơ khi bơi cự ly dài.', 'Tráng lại nước máy sau khi bơi hồ.', '{"fabric": "Vải ép nhiệt không đường chỉ may viền đùi", "fit": "Compression fit ôm cơ"}', '{"M": {"waist": "74-80cm"}, "L": {"waist": "81-87cm"}, "XL": {"waist": "88-94cm"}}', ARRAY['quan-boi-nam', 'thi-dau', 'jammer'], 'Selling'),
(12, 11, 1, 'SWIM-ACC04', 'chan-vit-tap-boi-chuyen-dung-soobin-power-fins', 'Chân Vịt Tập Bơi Chuyên Dụng Soobin Power Fins', 340000.00, 'Unisex', 'Chuyên nghiệp', 'Chân vịt ngắn làm từ cao su tự nhiên cao cấp giúp tăng cường lực đạp chân và hoàn thiện kỹ thuật bơi sải, bơi bướm.', 'Rửa sạch cát biển sau khi tập luyện.', '{"blade": "Lưỡi ngắn trợ lực linh hoạt", "foot_pocket": "Khoang chân cao su êm ái"}', '{"S": {"size": "36-38"}, "M": {"size": "39-41"}, "L": {"size": "42-44"}}', ARRAY['chan-vit', 'tap-boi', 'phu-kien'], 'Selling'),
(13, 5, 2, 'SWIM-P013', 'bikini-2-manh-cup-nguc-soobin-vintage-polka-13', 'Bộ Bikini 2 Mảnh Cúp Ngực Soobin Vintage Polka (Series #13)', 460000.00, 'Nữ', 'Nghỉ dưỡng', 'Vải dệt họa tiết chấm bi cổ điển, cúp ngực có gọng tôn dáng gợi cảm.', 'Giặt tay nhẹ nhàng bằng nước mát, phơi trong bóng râm.', '{"fabric": "82% Polyamide, 18% Elastane kháng Clo", "padding": "Đệm mút tháo rời", "uv_protection": "UPF 50+"}', '{"S": {"chest": "80-84cm", "waist": "62-66cm"}, "M": {"chest": "85-89cm", "waist": "67-71cm"}, "L": {"chest": "90-94cm", "waist": "72-76cm"}}', ARRAY['do-boi-nu', 'thoi-trang', 'chong-nang'], 'Selling'),
(14, 6, 1, 'SWIM-P014', 'ao-tam-1-manh-day-cheo-lung-soobin-crossback-14', 'Áo Tắm 1 Mảnh Liền Thân Dây Chéo Lưng Soobin CrossBack (Series #14)', 520000.00, 'Nữ', 'Bơi lội thể thao', 'Dây lưng đan chéo thanh mảnh khoe trọn lưng trần thon thả, vải kháng clo cao cấp.', 'Giặt tay nhẹ nhàng bằng nước mát, phơi trong bóng râm.', '{"fabric": "82% Polyamide, 18% Elastane kháng Clo", "padding": "Đệm mút tháo rời", "uv_protection": "UPF 50+"}', '{"S": {"chest": "80-84cm", "waist": "62-66cm"}, "M": {"chest": "85-89cm", "waist": "67-71cm"}, "L": {"chest": "90-94cm", "waist": "72-76cm"}}', ARRAY['do-boi-nu', 'thoi-trang', 'chong-nang'], 'Selling'),
